"""Readers for the configuration headers generated by the model OTA host tools."""

import re
from pathlib import Path


def config_define(path: Path, name: str) -> int | None:
    """Integer value of `#define <name> <value>` in the header at path, or None.

    Use only on headers generated by the model_ota tooling, which emit one plain
    `#define NAME <integer>` per line. This is a regex, not a C preprocessor: it does not
    handle line continuations, comments, expressions, octal literals or redefinitions.
    """
    match = re.search(
        rf"^\s*#define\s+{re.escape(name)}\s+(0[xX][0-9A-Fa-f]+|0|[1-9]\d*)[uUlL]*\s*$",
        path.read_text(encoding="utf-8"),
        re.MULTILINE,
    )
    return int(match.group(1), 0) if match else None
